const toggle=document.querySelector('#language-toggle');
const nodes=[];const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('script,style')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
while(walker.nextNode()){const node=walker.currentNode;const key=node.textContent.trim();if(dictionary[key])nodes.push({node,en:node.textContent,so:node.textContent.replace(key,dictionary[key])})}
